export function ErrorState({
  label = "{{label}}",
  value = "{{value}}",
  message = "{{message}}",
  accent = "{{accent}}",
  showError = {{showError}},
}) {
  return (
    <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430", maxWidth: 280 }}>
      <label htmlFor="es-react-1" style={{ display: "block", marginBottom: 6, fontWeight: 500 }}>{label}</label>
      <input id="es-react-1" type="text" defaultValue={value} aria-invalid={showError} aria-describedby={showError ? "es-react-msg-1" : undefined} style={{
        width: "100%", boxSizing: "border-box", padding: "10px 12px", font: "inherit", color: "#241430",
        background: showError ? `color-mix(in srgb, ${accent} 8%, #FAF7F2)` : "#FAF7F2",
        border: `1.5px solid ${showError ? accent : "#24143040"}`, borderRadius: 8,
      }} />
      {showError && <p id="es-react-msg-1" role="alert" style={{ margin: "6px 0 0", fontSize: 12, color: accent }}>{message}</p>}
    </div>
  );
}
